const btn=(label,action,icon='plus',cls='',data='')=>'<button type="button" class="btn '+cls+'" data-action="'+action+'" '+data+'>'+I(icon)+esc(label)+'</button>';
function empty(icon,title,text,button=''){return '<div class="empty">'+I(icon)+'<h3>'+esc(title)+'</h3><p>'+esc(text)+'</p>'+button+'</div>';}
